<?php
declare(strict_types=1);require __DIR__.'/_auth.php';$actor=$auth->requireLogin();$auth->requireRole('ADMIN');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$active=($_POST['active']??'')==='1';if(!$id||!$auth->users()->find($id)){http_response_code(400);exit('Invalid user');}if($id===$actor['id']&&!$active){http_response_code(400);exit('You cannot deactivate your own account');}$auth->users()->setActive($id,$active);$auth->audit()->log($active?'USER_ACTIVATED':'USER_DEACTIVATED',$actor['id'],$actor['username'],'USER',$id);$_SESSION['flash']='User status updated.';redirect('users.php');
